import { Host, h } from "@stencil/core";
import HeartIcon from "../../assets/svg/heart.svg";
import Helper from "../../Helpers/Helper";
/**
 * Standalone wishlist ("Fav") icon, meant to sit at the outer nav-bar level
 * next to `salla-user-menu` and `salla-cart-summary` — not nested inside the
 * account dropdown.
 *
 * A/B test: shown only on basic/plus stores (see Helper.getPlanName()) —
 * pro/special stores keep the pre-existing wishlist-in-menu-only experience.
 * TODO: confirm before/after click-count reporting comes from analytics.
 */
export class SallaWishlistSummary {
    constructor() {
        this.isEnabled = false;
        this.wishlistCount = 0;
        this.wishlistLabel = salla.lang.get('common.titles.wishlist');
        salla.wishlist.event.onAdded(() => this.syncCount());
        salla.wishlist.event.onRemoved(() => this.syncCount());
        // Server hydration (packages/twilight/src/api/wishlist.js syncStorageFromServer)
        // rewrites `salla::wishlist` in storage after the add/remove events above have
        // already fired, or without either firing at all — re-sync once it settles so
        // the badge doesn't stay stale.
        salla.event.on('wishlist::storage.synced', () => this.syncCount());
    }
    componentWillLoad() {
        return new Promise(resolve => salla.onReady(() => {
            const plan = Helper.getPlanName();
            this.isEnabled = !!plan && ['basic', 'plus'].includes(plan);
            this.syncCount();
            resolve();
        }));
    }
    syncCount() {
        this.wishlistCount = (salla.storage.get('salla::wishlist', []) || []).length;
    }
    render() {
        const is_guest = salla.config.isGuest();
        if (!this.isEnabled || is_guest) {
            return h(Host, { hidden: true });
        }
        return (h(Host, null, h("a", { class: "s-wishlist-summary-wrapper", href: salla.url.get('account/wishlist'), "aria-label": this.wishlistLabel }, h("i", { class: "s-wishlist-summary-icon", innerHTML: HeartIcon }), this.wishlistCount > 0 && (h("span", { class: "s-wishlist-summary-count" }, salla.helpers.number(this.wishlistCount))))));
    }
    static get is() { return "salla-wishlist-summary"; }
    static get originalStyleUrls() {
        return {
            "$": ["salla-wishlist-summary.scss"]
        };
    }
    static get styleUrls() {
        return {
            "$": ["salla-wishlist-summary.css"]
        };
    }
    static get states() {
        return {
            "isEnabled": {},
            "wishlistCount": {},
            "wishlistLabel": {}
        };
    }
}
